function currentIndex(x: number, width: number, selected: number): number {
    // Resolve against the currently expanded layout rather than a fixed x→photo
    // table. This preserves actual accordion handoff on repeated pointer moves.
    const first = geometry(0, selected, width).left, strip = width < 768 ? 4 : 8
    if (selected < 0) return clamp(Math.floor((x - first) / strip), 0, count - 1)
    const active = geometry(selected, selected, width)
    if (x < active.left) return clamp(Math.floor((x - first) / strip), 0, count - 1)
    if (x <= active.left + active.width) return selected
    return clamp(selected + 1 + Math.floor((x - active.left - active.width) / strip), 0, count - 1)
}

